<?php
declare(strict_types=1);
require_once __DIR__.'/EtsyWebhookPersistenceAcceptanceTest.php';
final class OrderCurrencyAcceptanceTest extends WP_UnitTestCase {
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();global $wpdb;$wpdb->query('START TRANSACTION');wp_set_current_user(0);}
 private function payload():array {(new ReflectionMethod(EtsyWebhookPersistenceAcceptanceTest::class,'historicalDigitalListing'))->invoke(new EtsyWebhookPersistenceAcceptanceTest());return ['event_type'=>'order.paid','order_id'=>(string)wp_rand(820000,829999),'shop_id'=>'712002','currency'=>'GBP','subtotal'=>24,'total'=>24,'line_items'=>[['listing_id'=>'712003','quantity'=>2,'price'=>12,'currency'=>'GBP']]];}
 private function accept(array $payload):array|WP_Error {$signed=(new ReflectionMethod(EtsyWebhookPersistenceAcceptanceTest::class,'signed'))->invoke(new EtsyWebhookPersistenceAcceptanceTest(),$payload);return (new DigiForge\Listings\EtsyWebhookIntake(new DigiForge\Listings\EtsyWebhookDeduplicator()))->accept($signed[1],$signed[2],$signed[3],$signed[4]);}
 public function testSignedIntakePreservesOriginalNonUsdOrderAndLineCurrencyWithoutConversion():void {$payload=$this->payload();$result=$this->accept($payload);self::assertNotWPError($result);global $wpdb;$order=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DigiForge\Database\Tables::orders().' WHERE id=%d',$result['order_id']),ARRAY_A);$line=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DigiForge\Database\Tables::order_line_items().' WHERE order_id=%d',$order['id']),ARRAY_A);self::assertSame('GBP',$order['currency']);self::assertSame('GBP',$line['currency']);self::assertEquals(24,$order['total_amount']);self::assertEquals(12,$line['unit_price_amount']);self::assertFalse($result['fulfillment_authorized']);}
 /** @dataProvider invalidCurrencyCases */
 public function testInvalidOrMissingMonetaryCurrencyCannotCreateAnAssumedUsdOrder(string $scope,mixed $currency):void {$payload=$this->payload();if($scope==='order_alias'){unset($payload['currency'],$payload['subtotal'],$payload['total']);$payload['total_amount']=24;}elseif($scope==='line_alias'){unset($payload['line_items'][0]['currency'],$payload['line_items'][0]['price']);$payload['line_items'][0]['price_amount']=12;}elseif($scope==='order'){if($currency===null)unset($payload['currency']);else $payload['currency']=$currency;}else $payload['line_items'][0]['currency']=$currency;$result=$this->accept($payload);self::assertWPError($result);self::assertStringContainsString('currency',$result->get_error_code());$order=(new DigiForge\Orders\Repository())->findByExternalReference($payload['order_id'],$payload['shop_id']);self::assertNull($order);self::assertTrue(DigiForge\Core\Settings::safety_locked());}
 public function invalidCurrencyCases():array{return [['order','not-a-currency'],['order',null],['line',['USD']],['order_alias',null],['line_alias',null]];}
}
